import{_ as a,C as n,o as s,c as i,a2 as e,E as r}from"./chunks/framework.TaNiW7i8.js";const f=JSON.parse('{"title":"First launch","description":"","frontmatter":{"title":"First launch"},"headers":[],"relativePath":"en/guide/first-run.md","filePath":"en/guide/first-run.md"}'),h={name:"en/guide/first-run.md"};function l(d,t,u,c,g,m){const o=n("Capture");return s(),i("div",null,[t[0]||(t[0]=e('<h1 id="first-launch" tabindex="-1">First launch <a class="header-anchor" href="#first-launch" aria-label="Permalink to &quot;First launch&quot;">​</a></h1><p>On first launch, Kessho does not yet know you or your memory. Instead of the home screen, it opens a five-step wizard: who you are, where the memory lives, what it contains, which AI assistants know about it, then a summary.</p><p>On the left, a dark panel keeps the brand and the list of steps: <strong>Identity</strong>, <strong>Location</strong>, <strong>Reconnaissance</strong>, <strong>Connectors</strong>, <strong>Summary</strong>. On the right, the current step, announced at the top (&quot;Step 2 of 5&quot;).</p><h2 id="the-steps" tabindex="-1">The steps <a class="header-anchor" href="#the-steps" aria-label="Permalink to &quot;The steps&quot;">​</a></h2><h3 id="_1-your-profile" tabindex="-1">1. Your profile <a class="header-anchor" href="#_1-your-profile" aria-label="Permalink to &quot;1. Your profile&quot;">​</a></h3><ol><li>Type your name in <strong>Name or Handle</strong>. This is how the assistant will address you.</li><li>If you like, add an <strong>Email</strong>. It is optional; if filled in, it must look like an address, otherwise the screen shows &quot;This cannot be an address&quot;.</li><li>Click <strong>Continue to the memory location</strong>. The button stays greyed out while the name is empty or the email typed is not plausible.</li></ol><h3 id="_2-the-memory-location" tabindex="-1">2. The memory location <a class="header-anchor" href="#_2-the-memory-location" aria-label="Permalink to &quot;2. The memory location&quot;">​</a></h3>',7)),r(o,{name:"premier-lancement",alt:"First launch, step 2 of 5: choosing the folder that will hold the memory (existing folder, previous install or a new memory)."}),t[1]||(t[1]=e('<p>Kessho suggests locations it found on your machine, each with its number of notes (&quot;does not exist yet&quot; instead, for a new memory):</p><ul><li><strong>New Kessho memory</strong>: a folder to be created, marked &quot;does not exist yet&quot;;</li><li><strong>Existing folder</strong>: a folder of notes already there, for example an Obsidian folder;</li><li><strong>Previous install</strong>: the folder of a previous installation, detected on your machine.</li></ul><p>A suggestion marked &quot;read-only&quot; refuses writes on this machine: you are better off picking another one.</p><ol><li>Click the suggestion that suits you. The <strong>Memory Path</strong> field fills in.</li><li>Or type a path in that field, or click <strong>Browse…</strong> to pick a folder.</li><li>Click <strong>Next</strong>. The button stays greyed out while the path is empty. <strong>Back</strong> returns to the previous step.</li></ol><p>To understand these choices, see <a href="/Kessho/en/guide/vault.html">Choose your memory</a>. The screen reminds you: &quot;You can change this later in the settings.&quot;</p><h3 id="_3-reconnaissance" tabindex="-1">3. Reconnaissance <a class="header-anchor" href="#_3-reconnaissance" aria-label="Permalink to &quot;3. Reconnaissance&quot;">​</a></h3><p>Kessho walks the folder to show you what it holds. Nothing is saved, and nothing stops you from moving on.</p><ol><li>Click <strong>Walk the folder</strong>.</li><li>A bar moves forward, with a count such as &quot;12 / 184 files read&quot; and the elapsed time. If some files cause trouble, the first warnings (five at most) appear below.</li><li>Click <strong>Next</strong> when the reading is done. You can also click <strong>Skip this step</strong> without walking anything.</li></ol><h3 id="_4-connectors" tabindex="-1">4. Connectors <a class="header-anchor" href="#_4-connectors" aria-label="Permalink to &quot;4. Connectors&quot;">​</a></h3><p>Your assistants can query your memory — provided they know about it. Nothing is written until you ask for it.</p><ol><li>Click <strong>Declare Kessho to my assistants</strong>.</li><li>Kessho lists the assistants it knows, each followed by &quot;declared&quot; or &quot;not detected&quot; (not installed on this machine: that is not a failure).</li><li>Click <strong>Next</strong>, or <strong>Skip this step</strong> to do it later.</li></ol><p>This step does the same thing as the <strong>Auto-inject</strong> button in the settings. The details are in <a href="/Kessho/en/guide/agents.html">Connect your agents</a>.</p><h3 id="_5-the-summary" tabindex="-1">5. The summary <a class="header-anchor" href="#_5-the-summary" aria-label="Permalink to &quot;5. The summary&quot;">​</a></h3><p>The &quot;Confirmation &amp; finalization&quot; screen repeats your choices: <strong>User</strong> and <strong>Memory Location</strong>.</p><ol><li>Check both values. <strong>Edit</strong> goes back.</li><li>Click <strong>Launch Kessho</strong>. The configuration is saved (&quot;Saving…&quot;) and the application opens.</li></ol><p>If saving fails, the message &quot;Error while saving the configuration&quot; appears and you stay on the screen.</p><h2 id="what-is-required" tabindex="-1">What is required <a class="header-anchor" href="#what-is-required" aria-label="Permalink to &quot;What is required&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Can you skip it?</th></tr></thead><tbody><tr><td>Identity</td><td>No: a name is needed.</td></tr><tr><td>Location</td><td>No: a path is needed.</td></tr><tr><td>Reconnaissance</td><td>Yes, with <strong>Skip this step</strong>.</td></tr><tr><td>Connectors</td><td>Yes, with <strong>Skip this step</strong>.</td></tr><tr><td>Summary</td><td>No: it is the step that saves.</td></tr></tbody></table><h2 id="running-the-wizard-again" tabindex="-1">Running the wizard again <a class="header-anchor" href="#running-the-wizard-again" aria-label="Permalink to &quot;Running the wizard again&quot;">​</a></h2><p>To go through it again, open <strong>Settings</strong>, section <strong>Reset</strong>, then <strong>Relaunch Onboarding Wizard</strong>. The configuration is cleared; the memory and its contents are left untouched. The button acts immediately, without asking for confirmation. See <a href="/Kessho/en/guide/settings.html">Settings</a>.</p><h2 id="what-next" tabindex="-1">What next? <a class="header-anchor" href="#what-next" aria-label="Permalink to &quot;What next?&quot;">​</a></h2><p>Once the wizard is closed, the application opens. Meet the <a href="/Kessho/en/guide/home.html">Home</a> screen.</p>',22))])}const y=a(h,[["render",l]]);export{f as __pageData,y as default};
